package local.chatagent.privatechat;
import android.app.*;import android.os.Bundle;import android.content.*;import android.net.Uri;import android.graphics.*;import android.media.ExifInterface;import android.view.*;import android.widget.*;import android.util.Base64;import org.json.*;import java.io.*;
public final class ProfileActivity extends Activity {
 private LocalStore store;private JSONObject config,profile;private String id,avatar="",draftKey;private boolean editable,loaded,busy,saved;private LinearLayout body,face;private EditText nickname,signature;private TextView region;private TextView status;private Button save;
 private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff344761);return t;}private LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setStateListAnimator(null);b.setElevation(0);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffedf3fd));b.setTextColor(0xff3478e5);b.setOnClickListener(v->action.run());return b;}
 public void onCreate(Bundle state){super.onCreate(state);store=LocalStore.get(this);id="agent".equals(getIntent().getStringExtra("person"))?"agent":"self";editable=id.equals("self");draftKey="profileDraft:"+store.readMeta("epoch","")+":"+id;try{config=Secrets.load(this);}catch(Exception ignored){}LinearLayout root=column();root.setBackgroundColor(0xfff5f7fb);root.setPadding(dp(20),dp(15),dp(20),dp(12));root.addView(button("‹ 返回",this::finish));root.addView(text(editable?"我的资料":"小鲸鱼资料",24));ScrollView scroll=new ScrollView(this);body=column();body.setPadding(0,dp(24),0,dp(20));face=column();body.addView(face);if(editable){body.addView(button("更换头像",()->{if(busy)return;if(!PhotoPicker.open(this,8))status.setText("无法打开系统相册，请检查相册应用是否可用。");}));body.addView(button("恢复默认头像",()->{if(busy)return;avatar="";showAvatar();}));}nickname=field("昵称",40);signature=field("个性签名",160);signature.setBackgroundColor(Color.TRANSPARENT);region=regionField();status=text("正在同步资料…",13);body.addView(status);if(editable){save=button("保存资料",this::saveProfile);save.setEnabled(false);body.addView(save);body.addView(button("重新读取已保存资料",()->new AlertDialog.Builder(this).setMessage("放弃尚未保存的修改，重新读取资料？").setNegativeButton("取消",null).setPositiveButton("读取",(d,n)->{store.meta(draftKey,"");load(true);}).show()));}scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);profile=ProfileData.read(store,id);if(editable){try{String draft=store.readMeta(draftKey,"");if(!draft.isEmpty())profile=new JSONObject(draft);}catch(Exception ignored){}}show();load(false);}
 private EditText field(String label,int max){TextView heading=text(label,13);heading.setPadding(0,dp(22),0,dp(6));body.addView(heading);EditText input=new EditText(this);input.setTextSize(16);input.setSingleLine(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(max)});input.setEnabled(editable);body.addView(input,new LinearLayout.LayoutParams(-1,dp(48)));return input;}
 private TextView regionField(){TextView label=text("所在地区",13);label.setPadding(0,dp(22),0,dp(6));body.addView(label);TextView value=text("",16);value.setGravity(Gravity.CENTER_VERTICAL);value.setPadding(dp(6),0,dp(6),0);value.setBackgroundColor(Color.TRANSPARENT);value.setHint(editable?"选择国家和省 / 州  ›":"未设置");value.setEnabled(editable);if(editable)value.setOnClickListener(v->{if(!busy)RegionPicker.show(this,value.getText().toString(),choice->{value.setText(choice);});});body.addView(value,new LinearLayout.LayoutParams(-1,dp(48)));return value;}
 private void show(){nickname.setText(profile.optString("nickname"));signature.setText(profile.optString("signature"));region.setText(profile.optString("region"));avatar=profile.optString("avatar");showAvatar();loaded=true;if(save!=null)save.setEnabled(true);}
 private void showAvatar(){face.removeAllViews();try{JSONObject p=new JSONObject().put("avatar",avatar);View view=ProfileData.avatar(this,p,editable);face.addView(view,new LinearLayout.LayoutParams(dp(88),dp(88)));}catch(Exception ignored){}}
 private JSONObject form()throws Exception{return new JSONObject().put("revision",profile.optLong("revision")).put("nickname",nickname.getText().toString()).put("signature",signature.getText().toString()).put("region",region.getText().toString()).put("avatar",avatar);}
 private void load(boolean discard){final String before;try{before=form().toString();}catch(Exception e){return;}SyncService.WORK.execute(()->{try{ProfileData.sync(new Api(config),store,store.readMeta("epoch",""));runOnUiThread(()->{if(isFinishing()||busy)return;try{if(discard||(!editable||store.readMeta(draftKey,"").isEmpty())&&form().toString().equals(before)){profile=ProfileData.read(store,id);show();}status.setText("");}catch(Exception ignored){}});}catch(Exception e){runOnUiThread(()->status.setText("暂时无法同步，已显示本机资料。"));}});}
 private void lockFields(boolean locked){nickname.setEnabled(editable&&!locked);signature.setEnabled(editable&&!locked);region.setEnabled(editable&&!locked);}
 private void saveProfile(){if(!editable||busy)return;try{final JSONObject value=form();if(value.getString("nickname").trim().isEmpty()){status.setText("昵称不能为空。");return;}busy=true;lockFields(true);save.setEnabled(false);store.meta(draftKey,value.toString());status.setText("正在保存…");SyncService.WORK.execute(()->{try{JSONObject result=new Api(config).object("/v1/profiles/self",value);ProfileData.saved(store,id,result);store.meta(draftKey,"");runOnUiThread(()->{profile=result;saved=true;busy=false;lockFields(false);show();status.setText("资料已保存。");});}catch(Exception e){runOnUiThread(()->{busy=false;lockFields(false);save.setEnabled(true);status.setText("PROFILE_CHANGED".equals(e.getMessage())?"资料已在电脑修改，请重新读取后核对。当前输入已保留。":"保存未完成，资料草稿已保留，请检查连接后重试。");});}});}catch(Exception e){status.setText("资料未保存，请检查输入。");}}
 protected void onPause(){super.onPause();if(editable&&loaded){try{JSONObject value=form();if(!value.toString().equals(profile.toString()))store.meta(draftKey,value.toString());else if(!busy)store.meta(draftKey,"");}catch(Exception ignored){}}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=8||result!=RESULT_OK||data==null||!editable||busy)return;Uri uri=data.getData();busy=true;save.setEnabled(false);status.setText("正在准备头像…");SyncService.WORK.execute(()->{try{ByteArrayOutputStream output=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(output.size()+n>10*1024*1024)throw new IOException();output.write(b,0,n);}}byte[] bytes=output.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<1||options.outHeight<1||(long)options.outWidth*options.outHeight>40000000)throw new IOException();options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>1024)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(image==null)throw new IOException();Matrix rotation=new Matrix();try{int orientation=new ExifInterface(new ByteArrayInputStream(bytes)).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);if(orientation==3)rotation.postRotate(180);if(orientation==6)rotation.postRotate(90);if(orientation==8)rotation.postRotate(270);if(orientation==2||orientation==4)rotation.postScale(-1,1);if(orientation==4)rotation.postRotate(180);if(orientation==5||orientation==7){rotation.postRotate(orientation==5?90:270);rotation.postScale(-1,1);}}catch(IOException ignored){}Bitmap oriented=Bitmap.createBitmap(image,0,0,image.getWidth(),image.getHeight(),rotation,true);int side=Math.min(oriented.getWidth(),oriented.getHeight());Bitmap crop=Bitmap.createBitmap(oriented,(oriented.getWidth()-side)/2,(oriented.getHeight()-side)/2,side,side);Bitmap square=Bitmap.createScaledBitmap(crop,256,256,true);ByteArrayOutputStream encoded=new ByteArrayOutputStream();square.compress(Bitmap.CompressFormat.PNG,100,encoded);final String encodedAvatar="data:image/png;base64,"+Base64.encodeToString(encoded.toByteArray(),Base64.NO_WRAP);runOnUiThread(()->{avatar=encodedAvatar;busy=false;save.setEnabled(true);showAvatar();status.setText("头像已预览，点击保存资料生效。");});}catch(Exception e){runOnUiThread(()->{busy=false;save.setEnabled(true);status.setText("无法读取图片，请选择 10 MB 以内的图片。");});}});}
}
